import json,statistics,html
from pathlib import Path
root=Path(r'historical-project\runs\project-v3\model-selection-20261020')
a=json.loads((root/'results.json').read_text(encoding='utf-8'));b=json.loads((root/'luna-followup/results.json').read_text(encoding='utf-8'))
rows=[]
for model in sorted({r['model'] for r in a}):
 data=[r for r in a+b if r['model']==model];t=[r['seconds'] for r in data]
 rows.append({'model':model,'n':len(t),'median_seconds':round(statistics.median(t),2),'mean_seconds':round(statistics.mean(t),2),'max_seconds':max(t),'strict_passes':sum(r['passed'] for r in data),'note':'Negation-only returns parsed + empty stages + unresolved text; backend rejects execution.' if len(t)>3 else ''})
print(json.dumps(rows,indent=2));(root/'combined-summary.json').write_text(json.dumps(rows,indent=2))
first=json.loads((root/'summary.json').read_text());table=''.join('<tr><td>'+html.escape(r['model'])+'</td><td>'+str(r['median_seconds'])+'</td><td>'+str(r['passed'])+'/3</td></tr>' for r in first)
more=''.join('<tr><td>'+r['model']+'</td><td>'+str(r['median_seconds'])+'</td><td>'+str(r['mean_seconds'])+'</td><td>'+str(r['max_seconds'])+'</td><td>'+str(r['strict_passes'])+'/9</td></tr>' for r in rows if r['n']==9)
page='''<!doctype html><meta charset="utf-8"><title>Demo\u89e3\u6790\u6a21\u578b\u901f\u5ea6\u5bf9\u6bd4</title><style>body{font:18px system-ui;max-width:1050px;margin:45px auto;padding:20px;color:#17354b}table{border-collapse:collapse;width:100%;margin:24px 0}td,th{padding:12px;text-align:left;border-bottom:1px solid #ccd}h1,h2{color:#087f8c}p{line-height:1.7}</style><h1>Demo\u89e3\u6790\u6a21\u578b\u901f\u5ea6\u5bf9\u6bd4</h1><p>\u7ed3\u8bba：Luna\u662f\u672c\u6b21\u6d4b\u8bd5\u4e2d\u6700\u5feb\u7684\u4e00\u7ec4。6 Luna\u5178\u578b\u54cd\u5e94\u7565\u5feb，5.6 Luna\u5e73\u5747\u7b49\u5f85\u66f4\u77ed、\u66f4\u7a33\u5b9a。\u5f53\u524dDemo\u4ecd\u4fdd\u6301Sol 6.1 Low；\u672c\u6b21\u53ea\u505a\u9009\u578b\u6d4b\u8bd5。</p><h2>\u76f8\u540c3\u6761\u6307\u4ee4，\u5168\u90e8\u6a21\u578b\u5747\u4f7f\u7528Low</h2><p>\u540c\u4e00\u73b0\u6709\u89e3\u6790\u63d0\u793a\u8bcd\u548cJSON\u683c\u5f0f；\u8ba1\u65f6\u5305\u542bPowerShell/Codex\u542f\u52a8、\u6a21\u578b\u8fd4\u56de\u548c\u8f93\u51fa\u4fdd\u5b58，\u4e0d\u5305\u62ec\u5730\u56fe\u89c4\u5212。\u6bcf\u8f6e\u6700\u591a3\u4e2a\u5e76\u53d1\u8bf7\u6c42，\u672a\u663e\u5f0f\u542f\u7528Fast\u6216Ultrafast。\u5c0f\u6837\u672c\u7ed3\u679c\u4e0d\u8868\u793a\u957f\u671f\u6392\u540d。</p><table><tr><th>\u6a21\u578b</th><th>\u8fd4\u56de\u65f6\u95f4\u4e2d\u4f4d\u6570（\u79d2）</th><th>\u901a\u8fc7</th></tr>'''+table+'''</table><h2>Luna\u8865\u6d4b\u540e，\u603b\u8ba1\u54049\u6761</h2><table><tr><th>\u6a21\u578b</th><th>\u4e2d\u4f4d\u6570（\u79d2）</th><th>\u5e73\u5747（\u79d2）</th><th>\u6700\u6162（\u79d2）</th><th>\u4e25\u683c\u68c0\u67e5</th></tr>'''+more+'''</table><p>8/9\u4e25\u683c\u901a\u8fc7。\u5171\u540c\u672a\u901a\u8fc7\u9879\u662f“Do not turn left.”：\u4e24\u8005\u5747\u8fd4\u56de\u7a7a\u52a8\u4f5c\u548c\u672a\u89e3\u51b3\u6587\u672c，\u6ca1\u6709\u751f\u6210\u5de6\u8f6c，\u540e\u53f0\u4f1a\u62d2\u7edd\u6267\u884c；\u4f46\u9876\u5c42\u72b6\u6001\u5199\u6210parsed，\u6ca1\u6709\u5199needs_clarification。\u52a8\u4f5c\u542b\u4e49\u5904\u7406\u6b63\u786e，\u72b6\u6001\u89c4\u8303\u5c1a\u9700\u4fee\u6b63。\u8986\u76d6：\u4e2d\u82f1\u6587\u591a\u6b65、\u8ddd\u79bb\u505c\u8f66、\u8f66\u9053\u5e8f\u53f7、\u6389\u5934、\u901f\u5ea6、\u82f1\u91cc/\u516c\u91cc\u6362\u7b97、\u6a21\u7cca\u6307\u4ee4、\u5426\u5b9a、\u7ea2\u7eff\u706f\u6761\u4ef6。\u672a\u6d4b\u8bd5\u4efb\u610f\u81ea\u7531\u8868\u8ff0\u6216\u6240\u6709doPlan\u6807\u7b7e。</p><p>\u6d4b\u8bd5\u65e5\u671f：2026-10-20，\u7528\u6237\u672c\u673a\u5f53\u524dCodex\u8ba2\u9605\u901a\u9053。\u539f\u59cb\u7ed3\u679c\u4fdd\u7559\u4e8eresults.json\u53caluna-followup/results.json。</p><h2>\u516c\u5f00\u8d44\u6599</h2><p><a href="https://artificialanalysis.ai/models/gpt-6-luna-low">Artificial Analysis：6 Luna Low</a> · <a href="https://artificialanalysis.ai/models/comparisons/gpt-6-1-sol-low-vs-gpt-6-astra-low">Astra Low\u4e0e6.1 Sol Low</a> · <a href="https://learn.chatgpt.com/docs/models">\u5f53\u524dCodex\u6a21\u578b\u4e0e\u9000\u5f79\u8303\u56f4</a></p>'''
(root/'comparison.html').write_text(page,encoding='utf-8')
